INSERT INTO `careers` (`id`, `category_id`, `job_title`, `sallery`, `vacancy`, `job_type`, `deadline`, `location`, `short_job_description`, `long_description`, `work_exp`, `created_at`, `updated_at`) VALUES
(4, 3, 'UI/UX Designer', '25,000 - 60,000 BDT/Month', 10, 'Full Time', '2024-12-31', 'Dhaka, Bangladesh', 'Ut imperdiet leo in arcu luctus non nunc moles suspends malasada dolon lobortis.', '<h1><span style=\"color: rgb(241, 241, 241)\">​Job Summary</span></h1><p><span style=\"color: rgb(241, 241, 241)\">[Company Name] is looking for a talented UI/UX Designer to enhance the visual and interactive aspects of our software products, ensuring intuitive and seamless user experiences. You’ll collaborate with our product and development teams to deliver innovative, user-centered designs.</span></p><h1><span style=\"color: rgb(241, 241, 241)\"><strong>Key Responsibilities</strong></span></h1><ul><li style=\"color: rgb(241, 241, 241)\">​Create user-friendly and intuitive interfaces for digital products.<br></li><li style=\"color: rgb(241, 241, 241)\">​Work closely with product management and engineering teams to align visuals with user experiences.</li><li style=\"color: rgb(241, 241, 241)\">​Stay informed about the latest trends and technologies in UI/UX design.</li><li style=\"color: rgb(241, 241, 241)\">​Simplify complex user scenarios with effective design solutions.</li><li style=\"color: rgb(241, 241, 241)\">Participate in design reviews and incorporate constructive feedback.</li><li style=\"color: rgb(241, 241, 241)\">Contribute to a consistent and cohesive brand identity across interfaces.​</li></ul><h1><span style=\"color: rgb(241, 241, 241)\">​Qualifications</span></h1><ul><li style=\"color: rgb(241, 241, 241)\">​Proven UI/UX design skills supported by a strong portfolio.</li><li style=\"color: rgb(241, 241, 241)\">​Proficiency in design tools such as Figma.</li><li style=\"color: rgb(241, 241, 241)\">​Solid understanding of user-centered design and usability principles.</li><li style=\"color: rgb(241, 241, 241)\">​Ability to transform product requirements into functional, user-friendly designs.</li><li style=\"color: rgb(241, 241, 241)\">​Excellent communication and presentation abilities.</li><li style=\"color: rgb(241, 241, 241)\">​Basic knowledge of front-end development (HTML5, CSS3) is a plus.</li><li style=\"color: rgb(241, 241, 241)\">​A keen eye for aesthetics and attention to detail.​</li></ul><h1><span style=\"color: rgb(241, 241, 241)\">​<strong>Why Join Us?</strong>​</span></h1><ul><li style=\"color: rgb(241, 241, 241)\">​Work on meaningful and impactful projects.</li><li style=\"color: rgb(241, 241, 241)\"><span style=\"color: rgb(241, 241, 241)\">Be part of a creative and supportive culture that fosters innovation.</span></li></ul><h1>​​​​Basic Benefits</h1><div class=\"se-component se-image-container __se__float-left\"><figure style=\"width: 16px;\"><img src=\"data:image/png;base64,\" alt=\"\" data-rotate=\"0\" data-proportion=\"false\" data-size=\"16px,16px\" data-align=\"left\" data-file-name=\"Vector (1).png\" data-file-size=\"1972\" origin-size=\"43,43\" data-origin=\"16px,16px\" style=\"width: 16px; height: 16px;\"></figure></div><p>Exceptional work culture and environment<br></p><div class=\"se-component se-image-container __se__float-left\"><figure style=\"width: 16px;\"><img src=\"data:image/png;base64,\" alt=\"\" data-rotate=\"0\" data-proportion=\"false\" data-size=\"16px,16px\" data-align=\"left\" data-file-name=\"Vector (1).png\" data-file-size=\"1972\" origin-size=\"43,43\" data-origin=\"16px,16px\" style=\"width: 16px; height: 16px;\"></figure></div><p>Free meals, coffee, and snacks<br></p><div class=\"se-component se-image-container __se__float-left\"><figure style=\"width: 16px;\"><img src=\"data:image/png;base64,\" alt=\"\" data-rotate=\"0\" data-proportion=\"false\" data-size=\"16px,16px\" data-align=\"left\" data-file-name=\"Vector (1).png\" data-file-size=\"1972\" origin-size=\"43,43\" data-origin=\"16px,16px\" style=\"width: 16px; height: 16px;\"></figure></div><p>Full-size gym to support wellness and fitness<br></p><div class=\"se-component se-image-container __se__float-left\"><figure style=\"width: 16px;\"><img src=\"data:image/png;base64,\" alt=\"\" data-rotate=\"0\" data-proportion=\"false\" data-size=\"16px,16px\" data-align=\"left\" data-file-name=\"Vector (1).png\" data-file-size=\"1972\" origin-size=\"43,43\" data-origin=\"16px,16px\" style=\"width: 16px; height: 16px;\"></figure></div><p>Facilities for both indoor and outdoor sports</p>', 'Any', '2024-12-23 01:52:42', '2024-12-23 03:23:56');
